function isPs3FolderGame(game){return ['infamous','infamous-2','the-sly-collection','jak-3','littlebigplanet-3','fight-night-champion','killzone-3','naughty-bear'].includes(game?.id);}
function isDefJam(game){return game?.id==='def-jam-fight-for-ny';}
function isSwitchFileGame(game){return ['super-smash-bros-ultimate','zelda-breath-of-the-wild','zelda-tears-of-the-kingdom','kirby-and-the-forgotten-land','super-mario-odyssey','super-mario-galaxy'].includes(game?.id);}
function isSecondSon(game){return ['infamous-second-son','infamous-first-light','killzone-shadow-fall','nba-street-vol-2'].includes(game?.id);}
function isPs5FolderGame(game){return ['nba-2k23-next-gen','marvels-wolverine','ghost-of-yotei','mlb-the-show-26','nhl-27'].includes(game?.id);}
