async function linkDiscord(relink=false){const c=modal('Link Discord');let state;try{state=await api.discordStatus()}catch{paragraph(c,'Could not check Discord connection. Please retry.');return}if(state.linked&&!relink){paragraph(c,'Connected as '+state.user.name);action(c,'Account settings',showSettings);action(c,'View Discord friends',showFriends);return}paragraph(c,'Link your Discord account and set up friends for NEXAVERSE. Approve account access, then the friends-access prompt from Discord. Linking also shares your Discord friend IDs with the NEXAVERSE community service to show mutual friends on launcher profiles.');if(!state.configured){paragraph(c,'Application setup required: the separate NEXAVERSE Discord application has not been created yet. Account authorization will become available after it is configured.');}else{action(c,'Authorize with Discord',async()=>{const b=c.querySelector('button');b.disabled=true;b.textContent='Waiting for Discord…';try{const result=await api.connectDiscord();if(!result.ok)throw Error(result.error);discordAccount=result.user;syncOwnProfile().catch(()=>{});$('#panel').close();updateDiscordIdentity();if(activePage==='profile')renderProfile();toast(result.friends?.status==='ready'?'Discord and friends connected':result.friends?.status==='error'?'Discord linked. Friends setup needs a retry in Friends.':'Discord linked. Approve friends access in Discord to finish.')}catch(e){toast(e.message);b.disabled=false;b.textContent='Authorize with Discord'}})}action(c,'Open community server',()=>api.openDiscordServer());}
$('#friendsCard').onclick=showFriends;


const profileKey=()=> 'sony-profile:'+(discordAccount?.id||'local');
function profilePreferences(){try{return JSON.parse(localStorage.getItem(profileKey()))||{}}catch{return {}}}
function updateProfilePreferences(patch){localStorage.setItem(profileKey(),JSON.stringify({...profilePreferences(),...patch}));renderProfile();syncOwnProfile().catch(()=>toast('Saved on this PC. Profile sharing could not sync; retry from Shared.'))}
function updateDiscordIdentity(){showMutualSharingNotice(discordAccount);if(selected==='welcome')$('#heroAction').textContent=discordAccount?'Discord linked':'Link Discord';const avatar=$('#profile');avatar.replaceChildren();if(discordAccount?.avatar){const photo=image(discordAccount.avatar,'Your Discord profile picture');photo.onerror=()=>{photo.remove();avatar.prepend(document.createTextNode(discordAccount?.name?.[0]||'N'))};avatar.append(photo)}else avatar.append(document.createTextNode(discordAccount?.name?.[0]||'N'));const dot=document.createElement('i');avatar.append(dot);$('#friendsSummary').textContent=discordAccount?'View Discord friends and connection status.':'Link Discord to get started.';$('.friends-state').textContent=discordAccount?'Account linked':'Not linked'}
function image(src,alt){const img=document.createElement('img');img.src=src;img.alt=alt||'';return img}
function block(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el}
const timeText=s=>Math.floor((s||0)/3600)+'h '+Math.floor((s||0)%3600/60)+'m';
function renderProfile(){const own=!viewedFriend,remote=(own?ownCommunity:visitorCommunity)?.profile,prefs=own?profilePreferences():{about:remote?.about,status:remote?.status};const display=own?discordAccount:(remote||viewedFriend);const list=own?games:(remote?.games||[]).map(g=>{const known=games.find(x=>x.id===g.id);return known?{...known,...g,exe:undefined,running:false,trophySummary:null}:null}).filter(Boolean);$('#profileDisplayName').textContent=display?.global_name||display?.name||display?.username||'Player One';updatePlaytimeBadge(list,display);$('#profileUsername').textContent=display?'@'+display.username:'Local profile';$('#profilePresence').textContent=own?({online:'Online in launcher',away:'Away in launcher',busy:'Do not disturb in launcher',invisible:'Appear offline in launcher'})[prefs.status||'online']:(remote?.status==='invisible'?'Offline in launcher':viewedFriend.source==='leaderboard'?'NEXAVERSE profile':viewedFriend.status+' on Discord');$('#profileLanguage').textContent=own?new Intl.DisplayNames([navigator.language],{type:'language'}).of(navigator.language.split('-')[0]):'';const picture=$('#profilePicture');picture.replaceChildren();if(display?.avatar)picture.append(image(display.avatar,'Discord avatar'));else picture.textContent=(display?.name||'N')[0];picture.dataset.status=prefs.status||'online';$('#profileBack').hidden=own;for(const id of ['profileStatusButton','profileEditAbout','profileOptions'])$('#'+id).hidden=!own;document.querySelectorAll('[data-profile-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.profileTab===profileTab);b.setAttribute('aria-selected',String(b.dataset.profileTab===profileTab))});const body=$('#profileTabContent');body.replaceChildren();if(!own&&visitorCommunity?.loading)body.append(block('p','profile-muted','Loading shared profile…'));if(!own&&visitorCommunity?.error){paragraph(body,visitorCommunity.error);action(body,'Retry profile',()=>showFriendProfile(viewedFriend))}
if(profileTab==='overview'){const grid=block('div','profile-overview-grid');const trophy=block('button','profile-summary trophy-summary');trophy.onclick=()=>$('#trophyCard').click();trophy.append(block('div','profile-trophy-level','Trophy collection'),block('strong','profile-zero',String(own?importedTrophyTotals().count:0)));const tiers=block('div','profile-small-tiers');for(const tier of ['platinum','gold','silver','bronze']){const item=block('div');item.append(image('assets/trophy-'+tier+'.png',tier+' trophy'),block('span','',String(own?importedTrophyTotals().tiers[tier]:0)));tiers.append(item)}const steamTier=block('div');steamTier.append(image('assets/trophy-steam.webp','Steam achievements'),block('span','',String(own?importedTrophyTotals().steamAchievements:0)));tiers.append(steamTier);const xboxTier=block('div');xboxTier.append(image('assets/trophy-xbox.svg','Xbox achievements'),block('span','',String(own?importedTrophyTotals().xboxAchievements:0)));tiers.append(xboxTier);const nintendoTier=block('div');nintendoTier.append(image('assets/trophy-nintendo.svg','Nintendo achievements'),block('span','',String(own?importedTrophyTotals().nintendoAchievements:0)));tiers.append(nintendoTier);trophy.append(tiers,block('p','summary-caption',own&&importedTrophyTotals().count?'NEXAVERSE trophy collection':'No verified trophies yet'));grid.append(trophy);const most=block('article','profile-summary most-played');most.append(block('h3','','Most played'));const played=list.filter(g=>g.seconds>0).sort((a,b)=>b.seconds-a.seconds).slice(0,3);if(!played.length)most.append(block('p','profile-muted',own?'Play a linked game to start recording your activity.':'No playtime shared yet.'));for(const g of played){const row=block('div','most-played-row');row.append(image(g.art,g.name));const text=block('div');text.append(block('span','',g.name),block('small','',timeText(g.seconds)));row.append(text);most.append(row)}grid.append(most);const library=block('button','profile-summary');library.onclick=()=>{profileTab='games';renderProfile()};const covers=block('div','profile-cover-strip');for(const g of list.slice(0,3))covers.append(image(g.art,g.name));library.append(covers,block('p','summary-caption','Games: '+list.length),block('small','',own?list.filter(g=>g.exe).length+' applications linked':'Total playtime: '+timeText(list.reduce((n,g)=>n+(g.seconds||0),0))));grid.append(library);const shared=block('button','profile-summary');shared.onclick=()=>{profileTab=own?'friends':'shared';renderProfile();if(own)loadOwnCommunity()};shared.append(block('div','profile-friends-symbol',own?'♧':'▧'),block('p','summary-caption',own?'Friends':'Shared screenshots'),block('small','',own?'View your Discord friends':((visitorCommunity?.media||[]).length+' screenshots')));grid.append(shared);body.append(grid,block('h3','about-heading','About'),block('div','about-copy',prefs.about||remote?.about||(!own&&!remote?'This friend has not shared a NEXAVERSE profile yet.':'No About Me added yet.')))}
else if(profileTab==='games'){const heading=block('div','profile-list-heading');const sortGroup=block('div','profile-sort-group');sortGroup.append(block('span','',profileGameSort==='time'?'Time played':'Recently played'));const sort=document.createElement('select');sort.className='profile-game-sort';sort.setAttribute('aria-label','Sort profile games');for(const [value,label]of [['recent','Recently played'],['time','Time played']]){const option=document.createElement('option');option.value=value;option.textContent=label;sort.append(option)}sort.value=profileGameSort;sort.onchange=()=>{profileGameSort=sort.value;localStorage.setItem('sony-profile-game-sort',profileGameSort);renderProfile()};sortGroup.append(sort);heading.append(sortGroup,block('span','','Trophy summary'));body.append(heading);const rows=block('div','profile-game-list');if(!list.length)paragraph(rows,'No games or playtime shared yet.');for(const g of [...list].sort((a,b)=>profileGameSort==='time'?((b.seconds||0)-(a.seconds||0)||(b.lastPlayed||0)-(a.lastPlayed||0)):((b.lastPlayed||0)-(a.lastPlayed||0)))){const row=block('div','profile-game-row'),gameButton=block('button','profile-game-main');gameButton.type='button';gameButton.append(image(g.art,g.name));const copy=block('div','profile-game-copy');copy.append(block('strong','',g.name),block('p','',g.running?'Playing now · '+timeText(g.seconds):'Played: '+(g.lastPlayed?new Date(g.lastPlayed).toLocaleDateString():'Not yet played')+'  |  Total playtime: '+timeText(g.seconds)));gameButton.append(copy);gameButton.onclick=()=>{selected=g.id;changePage('games');render()};const summary=block('button','profile-game-trophy');summary.type='button';summary.setAttribute('aria-label',g.name+' trophy summary');summary.onclick=()=>sonyTrophyBrowser.showGame(g,{readOnly:!own}).catch(e=>toast(e.message));row.append(gameButton,summary);rows.append(row);fillProfileTrophySummary(summary,g)}body.append(rows)}
else if(profileTab==='friends'){const empty=block('div','profile-empty');if(own)friendsContent(empty);else mutualFriendsContent(empty,viewedFriend);body.append(empty)}else renderShared(body,own)}
async function showFriendProfile(friend){viewedFriend=friend;profileTab='overview';visitorCommunity={loading:true};changePage('profile');try{const result=await api.communityProfile(friend.id);if(viewedFriend?.id!==friend.id)return;visitorCommunity=result}catch(e){if(viewedFriend?.id!==friend.id)return;visitorCommunity={error:e.message}}renderProfile()}
async function syncOwnProfile(){if(!discordAccount)return;const result=await api.saveCommunityProfile(profilePreferences());const fresh=result.profile;if(fresh&&fresh.id===discordAccount.id&&(fresh.avatar!==discordAccount.avatar||fresh.name!==discordAccount.name||fresh.username!==discordAccount.username)){discordAccount={...discordAccount,name:fresh.name,username:fresh.username,avatar:fresh.avatar};updateDiscordIdentity()}return result}
async function loadOwnCommunity(){if(!discordAccount)return;const id=discordAccount.id,generation=++ownCommunityRequest;ownCommunity={loading:true};try{const result=await api.communityProfile(id);if(discordAccount?.id!==id||generation!==ownCommunityRequest)return;ownCommunity=result}catch(e){if(discordAccount?.id!==id||generation!==ownCommunityRequest)return;ownCommunity={error:e.message}}if(activePage==='profile'&&!viewedFriend)renderProfile();if(activePage==='media')renderMedia()}
function renderShared(parent,own){window.nexaverseGallery.render(parent,{own})}
function renderMedia(){const parent=$('#mediaGallery');parent.replaceChildren();window.nexaverseGallery.render(parent,{own:true,mediaPage:true})}
$('#profileBack').onclick=()=>{viewedFriend=null;profileTab='friends';renderProfile()};
document.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{profileTab=b.dataset.profileTab;renderProfile();if(profileTab==='shared'&&!viewedFriend)loadOwnCommunity()});
$('#profileStatusButton').onclick=()=>{const c=modal('Account status');paragraph(c,'Your NEXAVERSE status. This does not change your Discord status.');for(const [value,label]of [['online','Online'],['away','Away'],['busy','Do not disturb'],['invisible','Appear offline']])action(c,label,()=>{updateProfilePreferences({status:value});$('#panel').close()})};
$('#profileEditAbout').onclick=()=>{const c=modal('Edit About Me'),input=document.createElement('textarea');input.maxLength=500;input.rows=5;input.value=profilePreferences().about||'';input.setAttribute('aria-label','About Me');c.append(input);paragraph(c,'With Discord linked, About Me is shared on your launcher profile. 500 characters maximum.');action(c,'Save',()=>{updateProfilePreferences({about:input.value.trim()});$('#panel').close()});input.focus()};
$('#profileOptions').onclick=showSettings;
window.addEventListener('nexaverse-controller-preview',event=>{if(activePage!=='games'||$('#panel').open)return;const id=event.detail?.id;if(!['welcome','library',...homeGames().map(g=>g.id)].includes(id))return;selected=id;render();[...document.querySelectorAll('[data-controller-tile]')].find(el=>el.dataset.controllerTile===id)?.focus({preventScroll:true});});
