api.discordStatus().then(s=>{discordAccount=s.user;updateDiscordIdentity();syncOwnProfile().then(()=>{if(activePage==='profile'&&!viewedFriend)loadOwnCommunity()}).catch(()=>{});if(activePage==='profile')renderProfile()}).catch(()=>{});
setInterval(()=>reload().catch(()=>{}),15000);

let sceneTarget=null,sceneSlot=0,sceneGeneration=0;
async function syncScene(){document.body.classList.toggle('welcome-selected',activePage==='games'&&selected==='welcome');const game=activePage==='games'?games.find(g=>g.id===selected):null;const target=game?.background||null;if(sceneTarget===target)return;sceneTarget=target;const generation=++sceneGeneration;const layers=[...document.querySelectorAll('.game-scene')];document.body.classList.toggle('has-game-scene',Boolean(target));if(!target){layers.forEach(l=>l.classList.remove('visible'));return}try{const asset=new Image();asset.src=target;await asset.decode();if(generation!==sceneGeneration)return;sceneSlot=1-sceneSlot;const layer=layers[sceneSlot];layer.style.backgroundImage='url("'+target+'")';layer.dataset.game=game.id;layer.classList.add('visible');layers[1-sceneSlot].classList.remove('visible')}catch{if(generation===sceneGeneration){document.body.classList.remove('has-game-scene');layers.forEach(l=>l.classList.remove('visible'));toast('Could not load this game’s background.')}}}

document.querySelectorAll('[data-window]').forEach(b=>b.onclick=async()=>{await api.windowAction(b.dataset.window);updateWindowButton()});async function updateWindowButton(){const s=await api.windowState();document.body.classList.toggle('window-restored',!s.filled);const b=document.querySelector('[data-window=maximize]');b.textContent=s.filled?'▣':'□';b.setAttribute('aria-label',s.filled?'Restore window':'Fill screen')}updateWindowButton().catch(()=>{});

function friendsForGame(game){return nexaverseGameFriends.forGame(socialSnapshot,game)}
function updateGameFriends(){const game=games.find(g=>g.id===selected);if(!game)return;const target=$('.game-friends-empty'),note=$('#gameFriendsCard p');if(socialSnapshot?.status==='ready'&&socialSnapshot.friendsLoaded!==false){const playing=friendsForGame(game);target.textContent=playing.length?playing.slice(0,3).map(f=>f.name).join(', '):'No friends playing right now';note.textContent=playing.length?'View '+playing.length+' playing · Open a friend’s profile':'Activity from friends playing through NEXAVERSE.'}else{target.textContent=['connecting','authorizing','ready'].includes(socialSnapshot?.status)?'Loading Discord friends…':'Connect Discord friends';note.textContent='See who’s playing with Discord.'}}
function gameFriendRow(friend){const row=block('button','discord-friend');row.type='button';row.setAttribute('aria-label','View '+friend.name+' profile');row.onclick=()=>{$('#panel').close();showFriendProfile(friend)};if(friend.avatar)row.append(image(friend.avatar,friend.name));else row.append(block('span','friend-initial',friend.name[0]||'?'));const copy=block('div');copy.append(block('strong','',friend.name),block('small','','@'+friend.username),block('p','','Playing now'));row.append(copy,block('span','friend-status',friend.status));return row}
function showGameFriends(game){const root=modal(game.name+' · Friends Who Play'),controls=block('div','friends-controls'),content=block('div','discord-friends-list');root.append(controls,content);let signature='',busy=false;const current=()=>$('#panel').open&&root.contains(content);async function refresh(){if(!current()||busy)return;busy=true;try{const snapshot=await api.discordFriends();if(!current())return;socialSnapshot=snapshot;updateGameFriends();const next=JSON.stringify(snapshot);if(signature===next)return;signature=next;controls.replaceChildren();content.replaceChildren();if(snapshot.status==='ready'&&snapshot.friendsLoaded!==false){action(controls,'Refresh friends',async()=>{try{await api.connectDiscordFriends();signature='';await refresh()}catch(e){toast(e.message)}});const playing=friendsForGame(game);if(playing.length)playing.forEach(friend=>content.append(gameFriendRow(friend)));else paragraph(content,'No friends playing this game right now.');paragraph(content,'Shows Discord friends playing through NEXAVERSE with activity sharing enabled.','game-friends-note')}else if(!discordAccount){paragraph(content,'Link Discord to see friends who play.');action(controls,'Link Discord',()=>linkDiscord())}else{paragraph(content,snapshot.message||'Loading Discord friends…');if(!['connecting','authorizing','ready'].includes(snapshot.status))action(controls,'Connect Discord friends',async()=>{try{await api.connectDiscordFriends();signature='';await refresh()}catch(e){toast(e.message)}})}action(controls,'View all friends',showFriends)}catch{if(current()){content.replaceChildren();paragraph(content,'Could not load Discord friends.');signature='';action(content,'Retry',refresh)}}finally{busy=false}}refresh();const poll=setInterval(()=>{if(!current()){clearInterval(poll);return}refresh()},1500)}
async function refreshSocialSummary(){socialSnapshot=await api.discordFriends();if(socialSnapshot.status==='ready'){$('.friends-state').textContent=socialSnapshot.friends.filter(f=>!['Offline','Invisible'].includes(f.status)).length+' online';$('#friendsSummary').textContent=socialSnapshot.friends.length+' Discord friends connected.';const faces=$('.friends-illustration');faces.replaceChildren();for(const f of socialSnapshot.friends.filter(f=>f.avatar&&!['Offline','Invisible'].includes(f.status)).slice(0,4))faces.append(image(f.avatar,''))}else{$('.friends-state').textContent=discordAccount?'Account linked':'Not linked';$('#friendsSummary').textContent=discordAccount?'Connect Discord friends to see who’s online.':'Link Discord to get started.';$('.friends-illustration').replaceChildren()}updateGameFriends()}
refreshSocialSummary().catch(()=>{});setInterval(()=>refreshSocialSummary().catch(()=>{}),3000);

setInterval(()=>syncOwnProfile().catch(()=>{}),60000);

function updatePlaytimeBadge(list,identity=discordAccount){const name=$('#profileDisplayName');name.querySelector('.playtime-plus')?.remove();if(!sonyPlusMemberIds.includes(identity?.id)&&list.reduce((total,g)=>total+Math.max(0,Number(g.seconds)||0),0)<3600)return;const badge=image('assets/playstation-plus.png','Playstation Plus Member');badge.className='playtime-plus';badge.title='Playstation Plus Member';badge.tabIndex=0;name.append(badge)}

async function updateLauncherActivity(){try{const activity=await api.launcherActivity();$('#totalTime').textContent=Math.floor(activity.seconds/3600)+'h '+Math.floor(activity.seconds%3600/60)+'m'}catch{}}updateLauncherActivity();setInterval(updateLauncherActivity,1000);

async function fillProfileTrophySummary(target,game){if(game.trophiesPending){target.append(block('span','profile-trophy-unverified','Trophy list coming later'));return}const progress=block('div','profile-trophy-column'),earned=block('div','profile-trophy-column'),summary=game.trophySummary;progress.append(block('span','profile-trophy-label','Progress'),block('strong','profile-trophy-value',summary?summary.percent+'%':'—'));const value=block('strong','profile-trophy-value',summary?summary.count+' / '+summary.total:'— / …');earned.append(block('span','profile-trophy-label','Earned'),value);target.append(progress,earned,block('small','profile-trophy-unverified',summary?(summary.source==='admin'?'Awarded by NEXAVERSE':'Imported from Steam'):'Not verified'));if(!summary)try{const data=await api.trophyList(game.id);if(target.isConnected)value.textContent='— / '+data.trophies.length}catch{if(target.isConnected)value.textContent='— / —'}}

window.addEventListener('resize',()=>updateWindowButton().catch(()=>{}));

document.querySelectorAll('[data-download-site]').forEach(button=>button.onclick=()=>api.openDownloadSite(button.dataset.downloadSite).catch(()=>toast('Could not open the website. Please try again.')));

async function mutualFriendsContent(parent,friend){parent.classList.add('friends-panel');const heading=block('h2','','Mutual friends'),content=block('div','discord-friends-list');parent.append(heading,content);paragraph(content,'Loading mutual friends…');try{const result=await api.mutualFriends(friend.id);if(!parent.isConnected||viewedFriend?.id!==friend.id)return;content.replaceChildren();if(result.status!=='ready'){paragraph(content,'Mutual friends unavailable');return}if(!result.friends.length){paragraph(content,'No mutuals');return}for(const mutual of result.friends){const row=block('button','discord-friend');row.type='button';row.onclick=()=>showFriendProfile(mutual);if(mutual.avatar)row.append(image(mutual.avatar,mutual.name));else row.append(block('span','friend-initial',mutual.name[0]));const copy=block('div');copy.append(block('strong','',mutual.name),block('small','','@'+mutual.username),block('p','',mutual.activity||mutual.status));row.append(copy,block('span','friend-status',mutual.status));content.append(row)}}catch{if(parent.isConnected){content.replaceChildren();paragraph(content,'Could not load mutual friends.');action(content,'Retry',()=>{parent.replaceChildren();mutualFriendsContent(parent,friend)})}}}

function showMutualSharingNotice(account){if(!account)return;const key='sony-mutual-notice:'+account.id;try{if(localStorage.getItem(key))return;localStorage.setItem(key,'1')}catch{}const notice=block('aside','mutual-sharing-notice');notice.setAttribute('role','status');notice.append(block('strong','','Mutual friends are now online'),block('p','','Your Discord friend IDs are shared with the NEXAVERSE community service to show mutual friends across launcher profiles.'));const close=block('button','','×');close.setAttribute('aria-label','Dismiss mutual friends notice');close.onclick=()=>notice.remove();notice.append(close);document.body.append(notice);setTimeout(()=>notice.remove(),15000)}

async function renderSteamSetting(root){root.replaceChildren(block('h3','','Steam account · Optional'));try{const steam=await api.steamStatus();if(!root.isConnected)return;paragraph(root,steam.linked?'Steam linked · '+steam.steamId:'Link your Steam account using Steam’s official sign-in page.');if(steam.message)paragraph(root,steam.message,'profile-muted');paragraph(root,steam.cloudLinked?'Sync updates playtime and earned achievements for all supported games in your Steam account. Steam-only achievements have their own icon and no trophy tier.':'Account linking is optional. Connect Discord before linking Steam to enable online achievement syncing.','profile-muted');if(steam.linked&&steam.cloudLinked)action(root,'Sync Steam playtime & achievements',async()=>{try{const result=await api.syncSteam();await reload();toast('Steam sync: '+result.synced+' games updated');if(result.errors.length){const details=modal('Steam sync results');for(const error of result.errors)paragraph(details,error);paragraph(details,'Steam achievements and supported trophy matches are imported. For private Steam data, set Game details to Public in your Steam profile privacy settings.')}}catch(e){toast(e.message)}});if(steam.temporary)action(root,'Retry Steam connection',()=>renderSteamSetting(root));if(steam.linked&&!steam.cloudLinked&&!steam.temporary)action(root,'Enable Steam achievement sync',async()=>{try{const result=await api.connectSteam();if(!result.ok)throw Error(result.error);await renderSteamSetting(root)}catch(e){toast(e.message)}});if(steam.linked)action(root,'Unlink Steam',async()=>{try{await api.disconnectSteam();await renderSteamSetting(root);toast('Steam unlinked')}catch{toast('Could not unlink Steam. Please retry.')}});else{const button=block('button','pill','Link Steam account');button.onclick=async()=>{button.disabled=true;button.textContent='Waiting for Steam…';try{const result=await api.connectSteam();if(!result.ok)throw Error(result.error);await renderSteamSetting(root);toast(result.cloudLinked?'Steam account linked':result.syncError||result.message||'Steam signed in; achievement sync still needs a connection.')}catch(e){toast(e.message);if(button.isConnected){button.disabled=false;button.textContent='Link Steam account'}}};root.append(button)}}catch{paragraph(root,'Could not check Steam account.');action(root,'Retry',()=>renderSteamSetting(root))}}

function importedTrophyTotals(){const result={steamAchievements:0,xboxAchievements:0,nintendoAchievements:0,count:0,total:0,tiers:{platinum:0,gold:0,silver:0,bronze:0}};for(const g of games){const p=g.trophySummary;if(!p)continue;result.steamAchievements+=p.steamAchievements||0;result.xboxAchievements+=p.xboxAchievements||0;result.nintendoAchievements+=p.nintendoAchievements||0;result.count+=p.trophyCount??Object.values(p.tiers).reduce((a,b)=>a+b,0);result.total+=p.total;for(const tier of Object.keys(result.tiers))result.tiers[tier]+=p.tiers[tier]||0}return result}
function updateImportedTrophyTotals(){const t=importedTrophyTotals();$('#trophyTotal').textContent=t.count;let steamCount=$('#steamAchievementCount');if(!steamCount){const item=block('div');item.append(image('assets/trophy-steam.webp','Steam achievements'));steamCount=block('span','','0');steamCount.id='steamAchievementCount';item.append(steamCount);$('#trophyCard .trophy-tiers')?.append(item)}if(steamCount)steamCount.textContent=t.steamAchievements;for(const tier of Object.keys(t.tiers))$('#'+tier+'Count').textContent=t.tiers[tier];const percent=t.total?Math.floor((t.count+t.steamAchievements)/t.total*100):0;$('#trophyPercent').textContent=percent+'%';$('#trophyCard .trophy-progress i').style.width=percent+'%';$('#trophyCard [role=progressbar]').setAttribute('aria-valuenow',String(percent))}



