function libraryPlatformFor(game){return isPs5FolderGame(game)?'ps5':isSecondSon(game)?'ps4':isPs3FolderGame(game)?'ps3':isSwitchFileGame(game)?'nintendo':'pc'}
function setupLibraryControls(){if($('#librarySort'))return;const toolbar=$('.library-toolbar'),tools=document.createElement('div'),sort=document.createElement('select'),platform=document.createElement('select');tools.className='library-sort-controls';Object.assign(tools.style,{display:'flex',gap:'10px',marginLeft:'auto'});for(const [value,label] of [['recent','Most Recent'],['newest','Newest'],['oldest','Oldest']]){const option=new Option(label,value);sort.add(option)}for(const [value,label] of [['all','All Platforms'],['ps5','PS5'],['ps4','PS4'],['ps3','PS3'],['nintendo','Nintendo']]){const option=new Option(label,value);platform.add(option)}sort.id='librarySort';platform.id='libraryPlatform';sort.value=librarySort;platform.value=libraryPlatform;for(const control of [sort,platform])Object.assign(control.style,{color:'#ecf0fa',background:'#17243a',border:'1px solid #7088aa',borderRadius:'8px',padding:'10px',fontSize:'14px'});sort.setAttribute('aria-label','Sort games');platform.setAttribute('aria-label','Filter by platform');sort.onchange=()=>{librarySort=sort.value;localStorage.setItem('nexaverse-library-sort',librarySort);renderGameLibrary()};platform.onchange=()=>{libraryPlatform=platform.value;localStorage.setItem('nexaverse-library-platform',libraryPlatform);renderGameLibrary()};tools.append(sort,platform);toolbar.insertBefore(tools,$('#librarySearch'))}
function renderGameLibrary(){setupLibraryControls();const grid=$('#libraryGrid');grid.replaceChildren();document.querySelectorAll('[data-library-filter]').forEach(button=>{const active=button.dataset.libraryFilter===libraryFilter;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});const list=games.filter(game=>(libraryFilter!=='linked'||game.exe)&&game.name.toLocaleLowerCase().includes(librarySearch.toLocaleLowerCase())&&(libraryPlatform==='all'||libraryPlatformFor(game)===libraryPlatform));const indexed=list.map((game,index)=>({game,index}));indexed.sort((a,b)=>librarySort==='recent'?(b.game.lastPlayed||0)-(a.game.lastPlayed||0)||a.index-b.index:librarySort==='newest'?b.index-a.index:a.index-b.index);$('#libraryCount').textContent=list.length+' '+(list.length===1?'game':'games');if(!list.length){paragraph(grid,'No games found.');return}for(const {game} of indexed){const item=block('button','library-game');item.type='button';item.setAttribute('aria-label',(game.pairingPending?'View ':game.exe?'Play ':'Link ')+game.name);item.append(image(game.art,game.name),block('strong','',game.name),block('small','',game.pairingPending?(game.id==='infamous-second-son'?'Coming Soon':'Pairing Coming Soon'):game.running?'Playing now':game.exe?'Play':'Link game'));item.disabled=Boolean(game.running);item.onclick=()=>openLibraryGame(game);const card=block('div','library-game-card');card.append(item);if((game.exe||isDefJam(game)||isSecondSon(game)||isPs3FolderGame(game)||isSwitchFileGame(game))&&!game.pairingPending){const options=block('button','library-game-options','•••');options.type='button';options.title='Game options';options.setAttribute('aria-label','Options for '+game.name);options.onclick=()=>showLibraryGameOptions(game);card.append(options)}grid.append(card)}}
