function openLibraryGame(game){if(game.pairingPending){const root=modal(game.name);paragraph(root,game.id==='infamous-second-son'?'Coming Soon':'Pairing Coming Soon');return}if(game.exe)return launchLibraryGame(game);const root=modal(game.name);paragraph(root,game.id==='gta-vi'?'Link your local GTA VI Xbox game_scarlett_master.exe.':isDefJam(game)?'Link your locally owned Def Jam: Fight for NY ISO.':isSwitchFileGame(game)?'Link your Nintendo Switch game file.':isPs3FolderGame(game)?'Link your PS3 game folder.':isSecondSon(game)?'Link your inFAMOUS Second Son PS4 game folder.':'Link this game’s Windows application to play from your library.');const link=block('button','pill',isDefJam(game)?'Link ISO':'Link game');root.append(link);link.onclick=async()=>{link.disabled=true;try{const result=await api.link(game.id);if(!result)return;await reload();const updated=games.find(g=>g.id===game.id);if(!root.contains(link))return;root.replaceChildren();paragraph(root,'Game linked. Ready to play.');action(root,'Play',()=>launchLibraryGame(updated))}catch(e){toast(e.message)}finally{link.disabled=false}}}
