 const memoryButton=action(root,'Set up GTA VI memory',async()=>{memoryButton.disabled=true;memoryStatus.textContent='Checking drives and Windows paging capacity…';try{const result=await api.gta6MemorySetup(game.gtaPagefileDrive||'auto');memoryStatus.textContent=result.message}catch(error){memoryStatus.textContent=error.message.replace(/^Error invoking remote method '[^']+': (?:Error: )?/, '')}finally{memoryButton.disabled=Boolean(game.running)}});memoryButton.disabled=Boolean(game.running);
 const controls=block('div','gta6-config-row');root.append(controls);controls.append(memoryButton);
